interface ModuleDefaultExportBindingPlan {
    readonly declaration: ts.ExportAssignment | ts.ClassDeclaration;
    readonly cName: string;
    readonly initialized: string;
    readonly gcRoot: string;
}

interface JsonModuleBindingPlan {
    readonly source: ts.SourceFile;
    readonly cName: string;
    readonly gcRoot: string;
}

interface ModuleNamespaceExportPlan {
    readonly name: string;
    readonly declaration: ts.Node;
    readonly getter: string;
}

interface ModuleNamespacePlan {
    readonly source: ts.SourceFile;
    readonly moduleId: string;
    readonly factory: string;
    exports: ModuleNamespaceExportPlan[];
    emitted: boolean;
}

export interface EmitProgramOptions {
    nativeAddons?: NativeAddonManifest;
    dynamicRequires?: DynamicRequireManifest;
    runtimeCode?: RuntimeCodeManifest;
    unsafeEval?: boolean;
    test262Observation?: Test262NativeObservationPlan;
}

export function emitProgram(
    graph: ModuleGraph,
    checker: ts.TypeChecker,
    options: EmitProgramOptions = {},
): EmittedProgram {
    const em = new Emitter(checker, graph, options);
    return em.run();
}

