    private emitHttpMetadataProperty(name: string): EmitResult | null {
        if (name === "METHODS") {
            const methods = [
                "ACL", "BIND", "CHECKOUT", "CONNECT", "COPY", "DELETE", "GET", "HEAD", "LINK", "LOCK",
                "M-SEARCH", "MERGE", "MKACTIVITY", "MKCALENDAR", "MKCOL", "MOVE", "NOTIFY", "OPTIONS",
                "PATCH", "POST", "PROPFIND", "PROPPATCH", "PURGE", "PUT", "QUERY", "REBIND", "REPORT",
                "SEARCH", "SOURCE", "SUBSCRIBE", "TRACE", "UNBIND", "UNLINK", "UNLOCK", "UNSUBSCRIBE",
            ];
            const array = this.freshTemp("_http_methods");
            const value = this.freshTemp("_http_method");
            const pieces = [
                `tsc_array_t* ${array} = tsc_array_new(sizeof(tsc_str_t*), ${methods.length})`,
                `tsc_str_t* ${value}`,
            ];
            for (const method of methods) {
                pieces.push(`${value} = ${this.stringLit(method)}`);
                pieces.push(`tsc_array_push_raw(${array}, &${value})`);
            }
            pieces.push(array);
            return { c: `({ ${pieces.join("; ")}; })`, ty: arrayType(T_STRING) };
        }
        if (name === "STATUS_CODES") {
            const statuses: readonly [string, string][] = [
                ["100", "Continue"], ["101", "Switching Protocols"], ["102", "Processing"], ["103", "Early Hints"],
                ["200", "OK"], ["201", "Created"], ["202", "Accepted"], ["203", "Non-Authoritative Information"],
                ["204", "No Content"], ["205", "Reset Content"], ["206", "Partial Content"], ["207", "Multi-Status"],
                ["208", "Already Reported"], ["226", "IM Used"], ["300", "Multiple Choices"], ["301", "Moved Permanently"],
                ["302", "Found"], ["303", "See Other"], ["304", "Not Modified"], ["305", "Use Proxy"],
                ["307", "Temporary Redirect"], ["308", "Permanent Redirect"], ["400", "Bad Request"], ["401", "Unauthorized"],
                ["402", "Payment Required"], ["403", "Forbidden"], ["404", "Not Found"], ["405", "Method Not Allowed"],
                ["406", "Not Acceptable"], ["407", "Proxy Authentication Required"], ["408", "Request Timeout"], ["409", "Conflict"],
                ["410", "Gone"], ["411", "Length Required"], ["412", "Precondition Failed"], ["413", "Payload Too Large"],
                ["414", "URI Too Long"], ["415", "Unsupported Media Type"], ["416", "Range Not Satisfiable"], ["417", "Expectation Failed"],
                ["418", "I'm a Teapot"], ["421", "Misdirected Request"], ["422", "Unprocessable Entity"], ["423", "Locked"],
                ["424", "Failed Dependency"], ["425", "Too Early"], ["426", "Upgrade Required"], ["428", "Precondition Required"],
                ["429", "Too Many Requests"], ["431", "Request Header Fields Too Large"], ["451", "Unavailable For Legal Reasons"],
                ["500", "Internal Server Error"], ["501", "Not Implemented"], ["502", "Bad Gateway"], ["503", "Service Unavailable"],
                ["504", "Gateway Timeout"], ["505", "HTTP Version Not Supported"], ["506", "Variant Also Negotiates"],
                ["507", "Insufficient Storage"], ["508", "Loop Detected"], ["509", "Bandwidth Limit Exceeded"],
                ["510", "Not Extended"], ["511", "Network Authentication Required"],
            ];
            const object = this.freshTemp("_http_status_codes");
            const pieces = [`tsc_object_t* ${object} = tsc_object_new()`];
            for (const [code, message] of statuses) {
                pieces.push(`tsc_object_set(${object}, ${this.stringLit(code)}, tsc_value_string(${this.stringLit(message)}))`);
            }
            pieces.push(`tsc_value_object(${object})`);
            return { c: `({ ${pieces.join("; ")}; })`, ty: T_VALUE };
        }
        if (name === "maxHeaderSize") return { c: "16384.0", ty: T_NUMBER };
        return null;
    }

