                    mapped.kind === "map" ||
                    mapped.kind === "set" ||
                    mapped.kind === "weakmap" ||
                    mapped.kind === "weakset" ||
                    mapped.kind === "weakref" ||
                    mapped.kind === "finregistry" ||
                    mapped.kind === "promise" ||
                    mapped.kind === "eventemitter" ||
                    mapped.kind === "event" ||
                    mapped.kind === "eventtarget" ||
                    mapped.kind === "date" ||
                    mapped.kind === "url" ||
                    mapped.kind === "urlsearchparams" ||
                    mapped.kind === "arraybuffer" ||
                    mapped.kind === "dataview" ||
                    mapped.kind === "hash" ||
                    mapped.kind === "hmac"
