            osPriority !== null &&
            ts.isPropertyAccessExpression(pa.expression) &&
            pa.expression.name.text === "priority" &&
            ts.isIdentifier(pa.expression.expression) &&
            this.isNamedImportFrom(pa.expression.expression, ["os", "node:os"], "constants")
